<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { ConsultaService as C } from '../../bindings/sitposse7/desktop/app'
import ModalFormulario from './ModalFormulario.vue'
import AcaoIcone from './AcaoIcone.vue'
import { mensagem } from '../formato'
const props=defineProps<{uuid:string}>(), emit=defineEmits<{fechar:[];salvo:[]}>()
const d=ref<any>(null),original=ref(''),erro=ref(''),ocupado=ref(false),descartar=ref(false),aba=ref('Identificação')
const secoes=['Identificação','Pessoas','Veículos','Animais','Itens','Área','Localização','Observações','Fotos']
const grupos:Record<string,[string,string][]>={Pessoas:[['pessoas_adultos','Adultos (18+)'],['pessoas_jovens','Jovens (12–17)'],['pessoas_criancas','Crianças (0–11)']],Veículos:[['veic_caminhoes','Caminhões'],['veic_automoveis_utilitarios','Automóveis, caminhonetes e utilitários'],['veic_motos_ciclomotores','Motocicletas e ciclomotores']],Animais:[['bov_adultos','Bovinos adultos'],['bov_bezerros','Bezerros e bezerras'],['equ_adultos','Equinos adultos'],['equ_potros','Potros']]}
const p=computed(()=>d.value?.propriedade),area=ref(''),lat=ref(''),lon=ref('')
let areaInicial='',latInicial='',lonInicial=''
onMounted(async()=>{try{d.value=JSON.parse(await C.DocumentoEdicao(props.uuid));original.value=JSON.stringify(d.value);area.value=p.value.area_valor_milesimos==null?'':String(p.value.area_valor_milesimos/1000);lat.value=p.value.lat==null?'':String(p.value.lat);lon.value=p.value.lon==null?'':String(p.value.lon);areaInicial=area.value;latInicial=lat.value;lonInicial=lon.value}catch(e){erro.value=mensagem(e)}})
function fechar(){if(d.value&&(JSON.stringify(d.value)!==original.value||area.value!==areaInicial||lat.value!==latInicial||lon.value!==lonInicial)){descartar.value=true}else emit('fechar')}
function numero(s:string){return Number(s.trim().replace(',','.'))}
async function salvar(){erro.value='';try{
 const a=area.value.trim();if(a&&!/^\d+(?:[.,]\d{1,3})?$/.test(a))throw Error('Área: informe valor não negativo com até 3 casas decimais.');p.value.area_valor_milesimos=a?Math.round(numero(a)*1000):null;if(!a)p.value.area_unidade=null;else if(!p.value.area_unidade)throw Error('Selecione a unidade da área.')
 if(lat.value!==latInicial||lon.value!==lonInicial){if(!lat.value.trim()&&!lon.value.trim()){for(const k of ['lat','lon','gps_origem','gps_precisao_m','gps_capturado_em','gps_satelites'])p.value[k]=null}else{const la=numero(lat.value),lo=numero(lon.value);if(!lat.value.trim()||!lon.value.trim()||!Number.isFinite(la)||!Number.isFinite(lo)||Math.abs(la)>90||Math.abs(lo)>180)throw Error('Informe latitude e longitude válidas.');if(la!==p.value.lat||lo!==p.value.lon){p.value.lat=la;p.value.lon=lo;p.value.gps_origem='manual';p.value.gps_precisao_m=null;p.value.gps_capturado_em=null;p.value.gps_satelites=null}}}
 for(const it of d.value.itens)if(!it.codigo_catalogo.endsWith('.outros'))it.nome_personalizado=null
 p.value.observacoes_relevantes=p.value.observacoes_relevantes?.trim()?p.value.observacoes_relevantes:null
 ocupado.value=true;await C.SalvarEdicao(props.uuid,JSON.stringify(d.value));emit('salvo')
}catch(e){erro.value=mensagem(e)}finally{ocupado.value=false}}
async function baixar(id:string){try{await C.BaixarFoto(id)}catch(e){erro.value=mensagem(e)}}
const codigoNovo=ref('')
function adicionar(){const c=d.value.catalogo.find((x:any)=>x.codigo===codigoNovo.value);if(!c)return;d.value.itens.push({uuid:'',codigo_catalogo:c.codigo,categoria:c.categoria,nome_personalizado:null,quantidade:1})}
</script>
<template><ModalFormulario titulo="Editar propriedade" :ocupado="ocupado" @fechar="fechar"><p v-if="erro" class="aviso-erro" role="alert">{{erro}}</p><template v-if="d"><p class="suave aviso-edicao">Correção da Central: não volta ao celular. Alterações posteriores enviadas pelo celular serão recusadas até a futura resolução de conflitos.</p><div class="editor-grade"><nav aria-label="Seções do cadastro"><button v-for="s in secoes" :key="s" :class="{primario:aba===s}" @click="aba=s">{{s}}</button></nav><form id="editar-propriedade" class="pilha" @submit.prevent="salvar">
<h3>{{aba}}</h3>
<template v-if="aba==='Identificação'"><label class="campo">Nome da propriedade *<input v-model="p.nome_propriedade" required maxlength="200"></label><label class="campo">Responsável *<input v-model="p.responsavel_familia" required maxlength="200"></label><p class="suave">A coleta, a equipe e o estudo de origem permanecem os mesmos.</p></template>
<template v-if="grupos[aba]"><label v-for="[k,t] in grupos[aba]" :key="k" class="campo">{{t}}<input v-model.number="p[k]" type="number" min="0" step="1" required></label></template>
<template v-if="aba==='Área'"><label class="campo">Área informada<input v-model="area" inputmode="decimal"></label><label class="campo">Unidade<select v-model="p.area_unidade"><option :value="null">Selecione</option><option value="ha">Hectares</option><option value="alq_paulista">Alqueire paulista</option></select></label><p class="suave">1 alqueire paulista = 2,42 ha. Área vazia permanece não informada.</p></template>
<template v-if="aba==='Localização'"><label class="campo">Latitude<input v-model="lat" inputmode="decimal"></label><label class="campo">Longitude<input v-model="lon" inputmode="decimal"></label><p class="suave">Graus decimais WGS84. Alterar os valores torna a origem manual, sem precisão GNSS.</p></template>
<label v-if="aba==='Observações'" class="campo">Observações relevantes<textarea v-model="p.observacoes_relevantes" rows="8" maxlength="4000"></textarea></label>
<template v-if="aba==='Itens'"><div v-for="(it,i) in d.itens" :key="i" class="item-editor"><label class="campo">Item<select v-model="it.codigo_catalogo"><option v-for="c in d.catalogo" :key="c.codigo" :value="c.codigo">{{c.nome_exibicao}} · {{c.categoria}}</option></select></label><label v-if="it.codigo_catalogo.endsWith('.outros')" class="campo">Nome personalizado<input v-model="it.nome_personalizado" required></label><label class="campo">Quantidade<input v-model.number="it.quantidade" type="number" min="1" step="1" required></label><AcaoIcone acao="Remover item ao salvar" icone="excluir" @click="d.itens.splice(i,1)" /></div><div class="linha"><select v-model="codigoNovo" aria-label="Item para adicionar"><option value="">Escolha um item</option><option v-for="c in d.catalogo" :key="c.codigo" :value="c.codigo">{{c.nome_exibicao}} · {{c.categoria}}</option></select><button type="button" @click="adicionar">Adicionar item</button></div></template>
<template v-if="aba==='Fotos'"><p class="suave">Remover uma foto aqui só terá efeito após salvar. O arquivo é preservado no histórico.</p><div class="fotos-editor"><div v-for="(f,i) in d.fotos" :key="f.uuid"><img :src="f.url || `/fotos/${f.uuid}.jpg`" alt="Foto da propriedade"><div class="linha"><AcaoIcone acao="Baixar foto" icone="baixar" @click="baixar(f.uuid)"/><AcaoIcone acao="Excluir foto ao salvar" icone="excluir" @click="d.fotos.splice(i,1)"/></div></div></div><p v-if="!d.fotos.length">Nenhuma foto.</p></template>
</form></div><div v-if="descartar" class="aviso-erro" role="alert"><p>Descartar as alterações não salvas?</p><button @click="descartar=false">Continuar editando</button> <button class="perigo" @click="emit('fechar')">Descartar e fechar</button></div></template><template #acoes><button :disabled="ocupado" @click="fechar">Cancelar</button><button class="primario" form="editar-propriedade" type="submit" :disabled="ocupado||!d">{{ocupado?'Salvando…':'Salvar alterações'}}</button></template></ModalFormulario></template>
<style scoped>.editor-grade{display:grid;grid-template-columns:170px minmax(0,1fr);gap:1.5rem;margin-top:1rem;min-height:340px}.editor-grade nav{display:flex;flex-direction:column;gap:.3rem;align-self:start}.editor-grade nav button{text-align:left}.item-editor{border-bottom:1px solid var(--regua);padding-bottom:1rem;display:grid;gap:.6rem}.fotos-editor{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:1rem}.fotos-editor img{width:100%;height:130px;object-fit:cover;border-radius:8px}.aviso-edicao{font-size:.85rem;padding:.75rem;background:var(--folha-2);border-radius:8px}@media(max-width:650px){.editor-grade{grid-template-columns:1fr}.editor-grade nav{flex-direction:row;flex-wrap:wrap}.editor-grade nav button{min-height:40px}}</style>
